import math

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_of_range(start, end):
    """Calculates lcm(start, start+1, ..., end)"""
    if start > end:
        return 1
    result = start
    for i in range(start + 1, end + 1):
        result = lcm(result, i)
    return result

N_values = [3, 4, 5]
K_values = list(range(1, 11))

results = {}

for n in N_values:
    results[n] = {}
    print(f"--- n = {n} ---")

    # We need k up to 10 to check ratio x_{k+1}/x_k and potentially x_{k+2}/x_{k+1}
    # We iterate up to K_values[-2] = 9 to ensure k+1 is within range for comparison.
    for k in K_values:

        x_k = lcm_of_range(k, k + n - 1)
        x_k_plus_1 = lcm_of_range(k + 1, k + n)

        ratio = x_k_plus_1 / x_k

        check_result = {
            "k": k,
            "x_k": x_k,
            "x_k_plus_1": x_k_plus_1,
            "ratio": ratio
        }

        if ratio == 1.0:
            # If ratio is 1, we need to check x_{k+2} > x_{k+1}
            # We must ensure k+2 and n are valid for x_{k+2}
            if k + 2 <= 11: # Limit check just for safety in this small test run
                x_k_plus_2 = lcm_of_range(k + 2, k + 2 + n - 1)
                check_result["x_k_plus_2"] = x_k_plus_2
                check_result["x_k_plus_2_gt_x_k_plus_1"] = x_k_plus_2 > x_k_plus_1
            else:
                check_result["x_k_plus_2"] = "N/A (k too large)"
                check_result["x_k_plus_2_gt_x_k_plus_1"] = "N/A"

        results[n][k] = check_result

        print(f"n={n}, k={k}: Ratio = {ratio:.6f}")

