import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm_range(start, end):
    if start > end:
        return 1
    result = start
    for i in range(start + 1, end + 1):
        result = (result * i) // gcd(result, i)
    return result

n = 3
L_k = lambda k: lcm_range(k + 1, k + n - 1)
def G_k(k):
    d_k = gcd(k, L_k(k))
    d_k_plus_n = gcd(k + n, L_k(k))
    return d_k / d_k_plus_n

# Test for n=3
k_values = [2, 3, 4, 5, 6, 7, 8, 9, 10]
results = {}
for k in k_values:
    g = G_k(k)
    results[k] = g

print("Results for G_k (n=3):", results)
